// Generating an app's agent-facing tool surface from its compiled schema.
//
// The gateway already stores a complete declarative description of every app —
// tables, column types and nullability, resource types, and per-verb access
// rules. That is enough to derive a typed tool list mechanically, with no
// per-app work by the developer and none by us. See docs/agent-tool-surface.md.
//
// This is deliberately pure and lives in the schema package rather than in the
// CLI: the same generation has to serve the local stdio proxy today and a
// gateway-hosted MCP endpoint later, and a tool list that differed between them
// would be a bug nobody could see.
import { isViaRule } from "./ir.js";
// Columns the platform owns. Never arguments: a model asked to supply `id` or
// `createdAt` will confidently supply the wrong one.
const SYSTEM_COLUMNS = new Set(['id', 'createdAt', 'updatedAt', 'created_at', 'updated_at', 'ownerPrincipal', 'owner_principal']);
// Naive but predictable. A wrong singular ("addres") is a cosmetic flaw in a
// tool name; an unpredictable one is a tool an agent cannot guess the sibling
// of, which is worse.
function singular(name) {
    if (name.endsWith('ies'))
        return `${name.slice(0, -3)}y`;
    if (name.endsWith('ss'))
        return name;
    if (name.endsWith('s'))
        return name.slice(0, -1);
    return name;
}
const JSON_TYPES = {
    text: 'string',
    uuid: 'string',
    integer: 'integer',
    bigint: 'integer',
    boolean: 'boolean',
    jsonb: 'object',
    timestamp: 'string',
};
function columnProperty(col) {
    return {
        type: JSON_TYPES[col.type],
        // The derived fallback is deliberately thin. It names the column and its
        // type, which the model could infer anyway; anything richer would be us
        // inventing intent the developer did not state.
        description: col.description ?? `${col.name} (${col.type})`,
    };
}
function writableColumns(table) {
    return table.columns.filter((c) => !SYSTEM_COLUMNS.has(c.name) && !c.primaryKey);
}
// A verb generates a tool only if the schema allows it directly.
//
// `none` is obvious. A `via` rule is the subtler case: the function is the
// mandatory path, so exposing the raw table verb would advertise a capability
// that does not exist. The function's own tool is the honest surface, and it is
// generated from the deploy manifest rather than from here.
function directlyAllowed(spec) {
    if (spec === undefined || spec === 'none')
        return false;
    if (isViaRule(spec))
        return false;
    return true;
}
function hidden(thing) {
    return thing.agentVisible === false;
}
function resourceIdProperty(resourceType) {
    return {
        type: 'string',
        description: `The ${resourceType} to act in. Get one from list_${resourceType}s.`,
    };
}
function tableTools(table, opts) {
    if (hidden(table))
        return [];
    const tools = [];
    const one = singular(table.name);
    const scope = opts.resourceType ? 'resource' : 'private';
    const noun = table.description ?? `rows in ${table.name}`;
    const where = opts.resourceType ? ` in a ${opts.resourceType}` : '';
    // Top-level tables are private-scope: you own your own rows, so there is no
    // access spec to consult and nothing to prune.
    const access = table.access ?? {};
    const allowed = (verb) => opts.resourceType ? directlyAllowed(access[verb]) : true;
    const scoped = (extra, required) => ({
        type: 'object',
        properties: {
            ...(opts.resourceType ? { resourceId: resourceIdProperty(opts.resourceType) } : {}),
            ...extra,
        },
        required: [...(opts.resourceType ? ['resourceId'] : []), ...required],
    });
    if (allowed('read')) {
        tools.push({
            name: `list_${table.name}`,
            description: `List ${noun}${where}. Newest first.`,
            inputSchema: scoped({ limit: { type: 'integer', description: 'How many to return. Default 50.' } }, []),
            binding: { kind: 'table', op: 'select', table: table.name, scope },
        });
    }
    const writable = writableColumns(table);
    if (allowed('create') && writable.length > 0) {
        tools.push({
            name: `create_${one}`,
            description: `Create ${table.description ? `— ${table.description}` : `a row in ${table.name}`}${where}.`,
            inputSchema: scoped(Object.fromEntries(writable.map((c) => [c.name, columnProperty(c)])), 
            // Required is derived from the schema rather than guessed: notNull
            // without a default is the only thing that genuinely cannot be omitted.
            writable.filter((c) => c.notNull && c.default === undefined).map((c) => c.name)),
            binding: { kind: 'table', op: 'insert', table: table.name, scope },
        });
    }
    if (allowed('update') && writable.length > 0) {
        tools.push({
            name: `update_${one}`,
            description: `Update one row in ${table.name}${where}. Only the fields you pass change.`,
            inputSchema: scoped({
                id: { type: 'string', description: 'The row to update.' },
                ...Object.fromEntries(writable.map((c) => [c.name, columnProperty(c)])),
            }, ['id']),
            binding: { kind: 'table', op: 'update', table: table.name, scope },
        });
    }
    if (allowed('delete')) {
        tools.push({
            name: `delete_${one}`,
            description: `Delete one row from ${table.name}${where}. This cannot be undone.`,
            inputSchema: scoped({ id: { type: 'string', description: 'The row to delete.' } }, ['id']),
            binding: { kind: 'table', op: 'delete', table: table.name, scope },
        });
    }
    return tools;
}
function resourceTools(resource) {
    if (hidden(resource))
        return [];
    // The entry point. Without it an agent has a set of tools all requiring a
    // resourceId and no way to obtain one — and, more importantly, this is where
    // per-instance roles surface. They cannot be pruned from the tool list (the
    // same principal may be admin of one channel and reader of another), so the
    // agent is told its role and can reason about it.
    const tools = [
        {
            name: `list_${resource.type}s`,
            description: `${resource.description ?? `The ${resource.type}s you belong to`}. ` +
                `Returns each one's id and your role in it.`,
            inputSchema: { type: 'object', properties: {} },
            binding: { kind: 'list_resources', resourceType: resource.type },
        },
    ];
    for (const table of resource.tables)
        tools.push(...tableTools(table, { resourceType: resource.type }));
    // A mounted table's rows are creator-owned but reachable in this context, so
    // the resource's access rules are the ones that apply here.
    for (const mount of resource.mounts)
        tools.push(...tableTools(mount, { resourceType: resource.type }));
    return tools;
}
// SchemaIR → the generator's input. The CLI holds an IR at deploy time; the
// gateway holds a compiled schema, and adapts it the same way.
export function toolSourceFromIR(ir) {
    return {
        tables: ir.tables,
        resources: ir.resources.map((r) => ({
            type: r.type,
            ...(r.description !== undefined ? { description: r.description } : {}),
            ...(r.agentVisible !== undefined ? { agentVisible: r.agentVisible } : {}),
            tables: r.tables,
            mounts: r.mounts.map((m) => {
                const top = ir.tables.find((t) => t.name === m.table);
                return {
                    name: m.table,
                    columns: top?.columns ?? [],
                    ...(top?.description !== undefined ? { description: top.description } : {}),
                    ...(top?.agentVisible !== undefined ? { agentVisible: top.agentVisible } : {}),
                    access: m.access,
                };
            }),
        })),
    };
}
/**
 * The whole agent-facing surface of one app.
 *
 * What is pruned here is only what the schema makes statically knowable:
 * `none` verbs, `via`-gated verbs, and anything the developer hid. Per-instance
 * roles are resolved at call time, because the same principal can hold
 * different roles in different instances of the same resource type.
 *
 * So the tool list is a capability *hint*. The query engine remains the
 * enforcement point, and a tool generated here can never exceed what the agent
 * could already do over HTTP with the credential it holds.
 */
export function generateAgentTools(source) {
    const tools = [];
    for (const table of source.tables)
        tools.push(...tableTools(table, {}));
    for (const resource of source.resources)
        tools.push(...resourceTools(resource));
    // Mounted tables appear once per resource type they are mounted into, and
    // two identically-named tools would make one of them unreachable.
    const seen = new Set();
    return tools.filter((t) => (seen.has(t.name) ? false : (seen.add(t.name), true)));
}
